#!/usr/bin/env bash
#
# Generates src/icons.c: the built-in apps' icons, icons/<app>.svg rendered by
# resvg at each size phone-ui draws them (128 px in the menu, 180 px on the
# "Coming soon" screen), as PNGs embedded in the binary (`just ui` takes them).
# The file name is the app's name in lower case (ui_app_icon_create() compares
# without case); an app without an SVG keeps its colored square with a symbol.
#
# The SVGs are 128 x 128 (viewBox 0 0 128 128): the whole icon, a square with
# rx 32 and the corners transparent, as the colored squares. No text: resvg would
# take whatever fonts the host has.
#
# Run in `nix develop` (resvg):
#   external/package/phone-ui/gen-icons.sh [dir]
# With a directory, the PNGs are also written there, to look at them.
#

set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
sizes="128 180"
out="$here/src/icons.c"
png_dir="${1:-}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

entries=""
{
	echo "/* Generated by gen-icons.sh from icons/<app>.svg, do not edit */"
	echo
	echo "#include \"ui.h\""
	for svg in "$here"/icons/*.svg; do
		name="$(basename "$svg" .svg)"
		[[ "$name" =~ ^[a-z][a-z0-9_]*$ ]] || { echo "$svg: name not [a-z][a-z0-9_]*" >&2; exit 1; }
		for size in $sizes; do
			png="$tmp/$name-$size.png"
			resvg -w "$size" -h "$size" "$svg" "$png"
			[ -z "$png_dir" ] || install -D -m 0644 "$png" "$png_dir/$name-$size.png"
			echo
			echo "static const uint8_t ${name}_${size}[] = {"
			od -An -v -tx1 "$png" | sed -e 's/ \([0-9a-f][0-9a-f]\)/0x\1, /g' -e 's/ *$//' -e 's/^/\t/'
			echo "};"
			entries+="	{ \"$name\", $size, ${name}_$size, sizeof(${name}_$size) },"$'\n'
		done
	done
	echo
	echo "const struct ui_icon ui_icons[] = {"
	printf "%s" "$entries"
	echo "};"
	echo "const unsigned ui_icon_count = sizeof(ui_icons) / sizeof(ui_icons[0]);"
} > "$tmp/icons.c"
mv "$tmp/icons.c" "$out"
